#include <ap_int.h>
#define FIR_TAP 8
void fir_filter(ap_int<16> in, ap_int<16> &out) {
#pragma HLS INTERFACE ap_ctrl_none port=return
#pragma HLS INTERFACE ap_none port=in
#pragma HLS INTERFACE ap_none port=out
#pragma HLS PIPELINE II=1
    static ap_int<16> shift_reg[FIR_TAP] = {0};
    const ap_int<16> filter_coeff[FIR_TAP] = {1,1,1,1,1,1,1,1};
#pragma HLS ARRAY_PARTITION variable=shift_reg complete dim=0
#pragma HLS ARRAY_PARTITION variable=filter_coeff complete dim=0
    ap_int<16> sum = 0;
    for(int i = FIR_TAP-1; i > 0; --i){
#pragma HLS UNROLL
        shift_reg[i] = shift_reg[i-1];
    }
    shift_reg[0] = in;
    for(int i = 0; i < FIR_TAP; ++i){
#pragma HLS UNROLL
        sum += shift_reg[i] * filter_coeff[i];
    }
    out = sum;
}

testbench:
#include <stdio.h>
#include <ap_int.h>
#define TAP 8
#define DATA_WIDTH 16
void fir_filter(ap_int<16> in, ap_int<16> &out);
int main() {
    ap_int<DATA_WIDTH> in_seq[16];
    ap_int<DATA_WIDTH> golden[16] = {0};
    for(int i = 0; i < 16; i++){
        in_seq[i] = i % 256;
    }
    for(int i = 0; i < 16; i++){
        ap_int<DATA_WIDTH> sum = 0;
        for(int k = 0; k < TAP; k++){
            if(i - k >= 0) sum += in_seq[i - k];
        }
        golden[i] = sum;
    }
    ap_int<DATA_WIDTH> out_data;
    for(int i = 0; i < 16; i++){
        fir_filter(in_seq[i], out_data);
        if(out_data != golden[i]){
            printf("Test failed at index %d, expected: %d, got: %d\n", i, (int)golden[i], (int)out_data);
            return -1;
        }
    }
    printf("All tests passed!\n");
    return 0;
}
